      "id": 396,
      "tenant_id": "edv_jr",
      "titulo": "POP-12: Estruturação, Elaboração e Alteração de Estatuto Social",
      "categoria": "juridico",
      "conteudo": "# POP-12 - Estruturação, Elaboração e Alteração de Estatuto Social\n**Área Responsável**: Governança & Terceiro Setor\n**Nível de Acesso**: Todos os Membros (Assessor, Gerente, Diretor, Presidente)\n\n## 1. Objetivo Operacional\nOrientar a elaboração, revisão e adequação de Estatutos Sociais para empresas juniores, associações civis sem fins lucrativos, entidades acadêmicas e organizações do terceiro setor, assegurando governança transparente, conformidade com a legislação federal e aptidão plena para registro perante o Cartório de Registro Civil de Pessoas Jurídicas (RCPJ).\n\n## 2. Pré-requisitos Sistêmicos\n* Roteiro de perguntas e diagnóstico institucional respondido pelos dirigentes da entidade.\n* Definição das categorias de associados, instâncias deliberativas e modelo de gestão da entidade.\n* Consulta à Lei Federal nº 13.267/2016 (no caso de EJs) ou Código Civil (arts. 53 a 61, no caso de Associações Gerais).\n\n## 3. Passo a Passo na Interface do EDbrain e na Prática Notarial\n1. **Estruturação dos Capítulos Obrigatórios**:\n   - **Denominação, Sede, Fins e Duração**: Razão social completa, sigla oficial, sede no município de registro e finalidade sem fins lucrativos.\n   - **Associados**: Requisitos para admissão, demissão e exclusão, direitos e deveres dos membros, vedação à remuneração de dirigentes e inexistência de responsabilidade solidária ou subsidiária dos associados pelas dívidas da entidade.\n   - **Órgãos da Administração**: Composição, mandatos e competências da Assembleia Geral (órgão soberano), Diretoria Executiva e Conselho Fiscal/Consultivo.\n   - **Processo Eleitoral e Quórum**: Regras transparentes para convocação de assembleias ordinárias e extraordinárias, quórum de instalação e quórum qualificado para alteração estatutária e dissolução da entidade.\n   - **Patrimônio e Regime Financeiro**: Fontes de recursos, aplicação integral dos resultados operacionais na manutenção e desenvolvimento dos objetivos institucionais e destinação do patrimônio líquido remanescente a outra entidade congênere em caso de dissolução.\n2. **Convocação e Assembleia de Aprovação**:\n   - Elaboração do Edital de Convocação com antecedência mínima prevista no estatuto anterior.\n   - Redação rigorosa da Ata da Assembleia Geral de Fundação ou Alteração Estatutária, contendo lista de presença com qualificação e assinatura dos membros votantes.\n3. **Registro Notarial no RCPJ**:\n   - Montagem do kit documental: Requerimento assinado pelo Presidente, duas vias do Estatuto assinadas pelo Presidente e com visto de advogado regular na OAB (art. 1º, § 2º da Lei 8.906/94), duas vias da Ata de Aprovação e comprovante de quitação dos emolumentos cartorários.\n   - Atualização do CNPJ perante a Receita Federal do Brasil via Coletor Nacional (REDESIM/DBE).\n\n## 4. Tratamento de Exceções & Suporte Coletivo\n* **Exigência Cartorária de Retificação**: Caso o oficial do RCPJ aponte nota devolutiva ou exigência (ex: falta de visto do advogado ou imprecisão em quórum), revise o texto pontualmente conforme a exigência e reapresente no prazo legal de 30 dias sem custo de nova prenotação. Comunique no canal `#governanca` para validação imediata.",
      "drive_url": "https://drive.google.com/drive/search?q=Estatuto%20Social",
      "autor_id": 1,
      "autor_nome": "Charles Junior (Presidência)",
      "autor_email": "charles.junior@edvjr.com.br",
      "created_at": "2026-10-05 14:26:18",
      "updated_at": "2026-10-05 14:26:18",
      "gerado_por_ia": 0,
      "trilha_derivada_id": null
